// Shared with Achille's website chat, so the app and the website behave
// alike. Generated by scripts/sync-shared.mjs: do not edit it here.

// Whether the widget should keep showing the "agent is typing" dots.
//
// The orchestrator can send a short interim line ("Je regarde ça tout de
// suite") while the run is still working. That bubble comes from the agent,
// but it is not the reply, so the dots must stay on until a real reply lands.
export interface AwaitingReplyMessage {
  from_agent: boolean;
  interim?: boolean;
}

export function isAwaitingReply(messages: readonly AwaitingReplyMessage[]): boolean {
  const last = messages[messages.length - 1];
  if (!last) return false;
  return !last.from_agent || last.interim === true;
}
